def transform(grid):
    # Read the marker colors at the grid's repeated horizontal and vertical
    # separator crossings; these intersections form the reduced output matrix.
    h,w=len(grid),len(grid[0])
    # separator color is the one creating recurring full lines
    colors={v for row in grid for v in row}
    frame=max(colors,key=lambda x:sum(sum(v==x for v in row)>=w-2 for row in grid)+sum(sum(grid[r][c]==x for r in range(h))>=h-2 for c in range(w)))
    rows=[r for r,row in enumerate(grid) if sum(v==frame for v in row)>=w-2]
    cols=[c for c in range(w) if sum(grid[r][c]==frame for r in range(h))>=h-2]
    # Only the junctions where at least one axis has marker dots encode output;
    # sample the top-left corner of each compartment.
    out=[]
    for r in rows[1:]:
        row=[]
        for c in cols[1:]:
            row.append(grid[r][c] if grid[r][c]!=frame else 0)
        out.append(row)
    # Remove all-zero outer rows/columns to keep the encoded marked area.
    while out and all(v==0 for v in out[0]):out.pop(0)
    while out and all(v==0 for v in out[-1]):out.pop()
    if out:
        while all(row and row[0]==0 for row in out):
            for row in out: row.pop(0)
        while all(row and row[-1]==0 for row in out):
            for row in out: row.pop()
    return out
